#include "morok/lang/rlah/segmenter.hpp"
#include <algorithm>
#include <cmath>
#include <cstring>
#include <map>
namespace morok::lang::rlah { namespace {
float sig(float x){return x>=0?1/(1+std::exp(-x)):std::exp(x)/(1+std::exp(x));}
float ent(const std::array<double,256>&c,double n){double h=0;for(double x:c){double p=(x+1)/(n+256);h-=p*std::log2(p);}return float(h);}
template<class T>void put(std::vector<std::uint8_t>&o,T x){for(std::size_t i=0;i<sizeof(T);++i)o.push_back(std::uint8_t(std::uint64_t(x)>>(8*i)));}
template<class T>bool get(std::span<const std::uint8_t>b,std::size_t&p,T&x){if(p>b.size()||sizeof(T)>b.size()-p)return false;std::uint64_t v=0;for(std::size_t i=0;i<sizeof(T);++i)v|=std::uint64_t(b[p++])<<(8*i);x=T(v);return true;}
}
float Scorer::score(const Candidate&c)const noexcept{if(c.bytes.size()<2||c.bytes.size()>8)return 0;float z=p[22+c.bytes.size()-2];for(int i=0;i<22;++i)z+=p[i]*c.features[i];return sig(z);}
bool Scorer::train(std::span<const Candidate>a,std::span<const float>y)noexcept{if(a.size()!=y.size()||a.size()<16)return false;std::array<double,29>g{};for(size_t n=0;n<a.size();++n){if(!a[n].reversible||a[n].bytes.size()<2||a[n].bytes.size()>8)return false;double d=(score(a[n])-std::clamp(y[n],0.F,1.F))/a.size();for(int i=0;i<22;++i)g[i]+=d*a[n].features[i];g[22+a[n].bytes.size()-2]+=d;}++step;double b1=1-std::pow(.9,double(step)),b2=1-std::pow(.999,double(step));for(int i=0;i<29;++i){m[i]=float(.9*m[i]+.1*g[i]);v[i]=float(.999*v[i]+.001*g[i]*g[i]);p[i]-=float(.001*(m[i]/b1)/(std::sqrt(v[i]/b2)+1e-8));if(!std::isfinite(p[i]))return false;}return true;}
std::vector<Candidate> Segmenter::evaluate(std::span<const std::uint8_t>b,std::span<const float>state){std::map<std::vector<std::uint8_t>,std::uint64_t> counts;for(size_t n=2;n<=8;++n)for(size_t i=0;i+n<=b.size();++i)++counts[std::vector<std::uint8_t>(b.begin()+i,b.begin()+i+n)];std::array<double,256>base{};for(auto x:b)base[x]++;float h0=ent(base,double(b.size()));std::vector<Candidate> out;for(auto&[k,f]:counts){if(f<c_.min_frequency||out.size()>=c_.max_candidates)continue;Candidate x;x.bytes=k;x.frequency=f;x.features[0]=std::min(1.F,float(std::log1p(double(f))/std::log1p(double(b.size()+1))));std::array<double,256>next{};double n=0;for(size_t i=0;i+k.size()<b.size();++i)if(std::equal(k.begin(),k.end(),b.begin()+i)){next[b[i+k.size()]]++;n++;}x.predictive=h0>1e-6?std::clamp((h0-ent(next,n))/h0,0.F,1.F):0;x.features[1]=x.predictive;for(int bit=0;bit<8;++bit){double ones=0;for(auto z:k)ones+=(z>>(7-bit))&1;x.features[2+bit]=float(2*ones/k.size()-1);}for(size_t i=0;i<std::min<size_t>(8,state.size());++i)x.features[10+i]=state[i];x.features[18]=float(k.size()-2)/6;bool seen[256]{};int distinct=0;for(auto z:k)if(!seen[z])seen[z]=true,distinct++;x.features[19]=float(distinct)/k.size();size_t overlap=0;for(size_t q=1;q<k.size();++q)if(std::equal(k.begin(),k.begin()+q,k.end()-q))overlap=q;x.features[20]=float(overlap)/k.size();x.features[21]=1;size_t saving=f*(k.size()-1);x.compression=saving>24+k.size()+f?float(saving-24-k.size()-f)/b.size():0;x.features[2]=x.compression;x.utility=w_.frequency*x.features[0]+w_.predictive*x.predictive+w_.compression*x.compression+w_.preservation;x.score=s_.score(x);out.push_back(std::move(x));}std::sort(out.begin(),out.end(),[](auto&a,auto&b){return a.utility==b.utility?a.bytes<b.bytes:a.utility>b.utility;});std::vector<std::vector<std::uint8_t>> next;for(auto&x:out){bool was=std::find(active_.begin(),active_.end(),x.bytes)!=active_.end();x.active=was?x.utility>=c_.keep:x.utility>=c_.create;if(x.active&&next.size()<c_.max_active)next.push_back(x.bytes);else x.active=false;}active_=std::move(next);double d[3]={.05*(.25-(out.empty()?0:out[0].features[0]))/.25,.05*(.02-(out.empty()?0:out[0].predictive))/.02,.05*(.05-(out.empty()?0:out[0].compression))/.05};double w[3]={w_.frequency*std::exp(d[0]),w_.predictive*std::exp(d[1]),w_.compression*std::exp(d[2])};for(int z=0;z<12;++z){double sum=0;for(int i=0;i<3;++i){w[i]=std::clamp(w[i],.05,i==0?.20:.60);sum+=w[i];}for(double&v:w)v+=(.75-sum)/3;}double sum=w[0]+w[1]+w[2];if(std::abs(sum-.75)<1e-4)w_={float(w[0]),float(w[1]),float(w[2]),.25};return out;}
std::uint32_t crc32(std::span<const std::uint8_t>b)noexcept{std::uint32_t c=~0U;for(auto x:b){c^=x;for(int i=0;i<8;++i)c=(c>>1)^((c&1)?0xedb88320U:0);}return ~c;}
Encoded encode(std::span<const std::uint8_t>raw,std::span<const Candidate>cs){Encoded r;std::vector<Candidate>d;for(auto&c:cs)if(c.active&&c.bytes.size()>=2&&c.bytes.size()<=32&&d.size()<64)d.push_back(c);std::sort(d.begin(),d.end(),[](auto&a,auto&b){return a.utility==b.utility?a.bytes<b.bytes:a.utility>b.utility;});std::vector<std::uint8_t>tokens;uint32_t count=0;for(size_t p=0;p<raw.size();){size_t best=d.size();for(size_t i=0;i<d.size();++i)if(d[i].bytes.size()<=raw.size()-p&&std::equal(d[i].bytes.begin(),d[i].bytes.end(),raw.begin()+p)&&(best==d.size()||d[i].bytes.size()>d[best].bytes.size()))best=i;if(best==d.size()){tokens.push_back(0);tokens.push_back(raw[p++]);}else{tokens.push_back(1);tokens.push_back(uint8_t(best));p+=d[best].bytes.size();}++count;}std::vector<uint8_t>o{'R','L','A','H'};put<uint16_t>(o,1);put<uint16_t>(o,1);put<uint32_t>(o,uint32_t(raw.size()));put<uint16_t>(o,uint16_t(d.size()));put<uint16_t>(o,0);put<uint32_t>(o,count);put<uint32_t>(o,crc32(raw));for(auto&x:d){o.push_back(uint8_t(x.bytes.size()));o.insert(o.end(),x.bytes.begin(),x.bytes.end());}o.insert(o.end(),tokens.begin(),tokens.end());if(o.size()<raw.size())r.data=std::move(o),r.compressed=true;else{r.data={'R','L','A','H'};put<uint16_t>(r.data,1);put<uint16_t>(r.data,0);put<uint32_t>(r.data,uint32_t(raw.size()));put<uint16_t>(r.data,0);put<uint16_t>(r.data,0);put<uint32_t>(r.data,uint32_t(raw.size()));put<uint32_t>(r.data,crc32(raw));r.data.insert(r.data.end(),raw.begin(),raw.end());}return r;}
bool decode(std::span<const uint8_t>b,std::vector<uint8_t>&o,std::string&e){auto fail=[&](const char*m){o.clear();e=m;return false;};if(b.size()<24||std::memcmp(b.data(),"RLAH",4))return fail("bad header");size_t p=4;uint16_t v,f,dc,res;uint32_t len,n,crc;if(!get(b,p,v)||!get(b,p,f)||!get(b,p,len)||!get(b,p,dc)||!get(b,p,res)||!get(b,p,n)||!get(b,p,crc)||v!=1||f>1||dc>64||res||len>64*1024*1024)return fail("invalid header fields");std::vector<std::vector<uint8_t>>d;for(int i=0;i<dc;++i){if(p>=b.size())return fail("short dictionary");size_t z=b[p++];if(z<2||z>32||z>b.size()-p)return fail("bad dictionary entry");d.emplace_back(b.begin()+p,b.begin()+p+z);p+=z;}o.clear();o.reserve(len);if(!f){if(dc||n!=len||b.size()-p!=len)return fail("bad raw payload");o.insert(o.end(),b.begin()+p,b.end());}else for(uint32_t i=0;i<n;++i){if(p>=b.size())return fail("short token");auto t=b[p++];if(!t){if(p>=b.size()||o.size()>=len)return fail("bad literal");o.push_back(b[p++]);}else if(t==1){if(p>=b.size())return fail("short reference");auto id=b[p++];if(id>=d.size()||d[id].size()>len-o.size())return fail("bad reference");o.insert(o.end(),d[id].begin(),d[id].end());}else return fail("unknown token");}if(p!=b.size())return fail("trailing payload bytes");if(o.size()!=len)return fail(("decoded length mismatch: expected "+std::to_string(len)+" got "+std::to_string(o.size())).c_str());const auto actual_crc=crc32(o);if(actual_crc!=crc)return fail(("checksum mismatch: expected "+std::to_string(crc)+" got "+std::to_string(actual_crc)).c_str());e.clear();return true;}
}